from collections import deque

def get_connected_regions(grid, start_value):
    rows = len(grid)
    cols = len(grid[0])

    visited = set()
    regions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == start_value and (r, c) not in visited:
                # BFS to find region
                queue = [(r, c)]
                region = [(r, c)]
                visited.add((r, c))
                while queue:
                    cr, cc = queue.pop(0)
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == start_value and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                region.append((nr, nc))
                                queue.append((nr, nc))
                regions.append(region)

    return regions

