# Define functions for checking enclosure
def is_horizontally_enclosed(grid, r, c):
    """Check if position (r,c) has 9s on left and right with gap <= 5"""
    row = grid[r]
    # Find nearest 9s in directions
    left_9_idx = None
    right_9_idx = None

    for i in range(c-1, -1, -1):
